    [ Chart.StackedBar(values = values, Keys = keys, Name = &quot;old&quot;)
      Chart.StackedBar(values = [ 8; 21; 13 ], Keys = keys, Name = &quot;new&quot;) ]
    |&gt; Chart.combine

