    Chart.AnnotatedHeatmap(
        zData = [ [ 1..5 ]; [ 6..10 ]; [ 11..15 ] ],
        annotationText = [ [ &quot;1,1&quot;; &quot;1,2&quot;; &quot;1,3&quot; ]; [ &quot;2,1&quot;; &quot;2,2&quot;; &quot;2,3&quot; ]; [ &quot;3,1&quot;; &quot;3,2&quot;; &quot;3,3&quot; ] ],
        X = [ &quot;C1&quot;; &quot;C2&quot;; &quot;C3&quot; ],
        Y = [ &quot;R1&quot;; &quot;R2&quot;; &quot;R3&quot; ],
        ReverseYAxis = true
    )

